package main

import (
	"encoding/json"
	"os"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/corentings/chess/v2"
)

type candidateProbeCase struct {
	ID, Position, FEN string
	Deep              bool
}

func candidateProbeCases(t testing.TB) []candidateProbeCase {
	t.Helper()
	b, err := os.ReadFile(os.Getenv("CANDIDATE_INPUT"))
	if err != nil {
		t.Fatal(err)
	}
	var input struct{ Cases []candidateProbeCase }
	if err := json.Unmarshal(b, &input); err != nil {
		t.Fatal(err)
	}
	return input.Cases
}

func candidateProbeGame(t testing.TB, c candidateProbeCase) *chess.Game {
	t.Helper()
	text := strings.TrimPrefix(c.Position, "position ")
	if text == "" {
		text = "fen " + c.FEN
	}
	g, err := parsePosition(strings.Fields(text))
	if err != nil {
		t.Fatal(err)
	}
	return g
}

func TestCandidateFixedWork(t *testing.T) {
	output := os.Getenv("CANDIDATE_OUTPUT")
	if output == "" {
		t.Skip("explicit diagnostic input/output required")
	}
	depth := 4
	if raw := os.Getenv("CANDIDATE_DEPTH"); raw != "" {
		n, err := strconv.Atoi(raw)
		if err != nil {
			t.Fatal(err)
		}
		depth = n
	}
	type result struct {
		ID       string
		Depth    int
		Nodes    uint64
		Score    int
		Best     []string
		MS       float64
		Complete bool
	}
	rows := []result{}
	for _, c := range candidateProbeCases(t) {
		if depth > 4 && !c.Deep {
			continue
		}
		g := candidateProbeGame(t, c)
		p := g.Position()
		w := searcher{table: newTable(), killers: new(killerTable), deadline: time.Now().Add(30 * time.Second)}
		for _, k := range repetitionHistory(g) {
			w.pushKey(k)
		}
		moves := rootMoves(p, nil)
		start := time.Now()
		best, score, complete := w.root(p, moves, depth)
		rows = append(rows, result{c.ID, depth, w.nodes, score, best, float64(time.Since(start)) / float64(time.Millisecond), complete})
		data, err := json.MarshalIndent(rows, "", "  ")
		if err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(output, append(data, '\n'), 0644); err != nil {
			t.Fatal(err)
		}
		if !complete {
			t.Fatal("incomplete fixed work", c.ID)
		}
	}
}

func BenchmarkCandidateProfile(b *testing.B) {
	if os.Getenv("CANDIDATE_INPUT") == "" {
		b.Skip("explicit input required")
	}
	cases := candidateProbeCases(b)
	games := make([]*chess.Game, len(cases))
	for i, c := range cases {
		games[i] = candidateProbeGame(b, c)
	}
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		g := games[i%len(games)]
		w := searcher{table: newTable(), killers: new(killerTable)}
		for _, k := range repetitionHistory(g) {
			w.pushKey(k)
		}
		_, _, ok := w.root(g.Position(), rootMoves(g.Position(), nil), 4)
		if !ok {
			b.Fatal("interrupted")
		}
	}
}

files.quiet_mate_test.go:
package main

import (
	"encoding/json"
	"math/rand/v2"
	"os"
	"testing"
	"time"

	"github.com/corentings/chess/v2"
)

func quietMateOracle(p *chess.Position) (chess.Move, bool) {
	if inCheck(p) {
		return chess.Move{}, false
	}
	for _, m := range p.ValidMoves() {
		if !m.HasTag(chess.Capture) && !m.HasTag(chess.EnPassant) && m.Promo() == chess.NoPieceType && p.Update(&m).Status() == chess.Checkmate {
			return m, true
		}
	}
	return chess.Move{}, false
}

func TestQuietMateProofSavedControls(t *testing.T) {
	b, err := os.ReadFile("tools/benchmark/research/v0.19-sharp-branches/training-quiet-threat-scan.json")
	if err != nil {
		t.Fatal(err)
	}
	var data struct {
		Rows []struct {
			ID      string
			Witness struct{ FEN string }
			Mates   []struct{ Move string } `json:"side_to_move_mates_in_one"`
		}
	}
	if err := json.Unmarshal(b, &data); err != nil {
		t.Fatal(err)
	}
	positives := 0
	for _, row := range data.Rows {
		p := evalFEN(t, row.Witness.FEN)
		before, hash := p.String(), p.ZobristHash()
		move, got := p.QuietMateMove()
		if got != (len(row.Mates) > 0) {
			t.Fatalf("proof mismatch %s %s", row.ID, row.Witness.FEN)
		}
		if got {
			positives++
			if p.Update(&move).Status() != chess.Checkmate {
				t.Fatal("not mate", move)
			}
			w := searcher{}
			score, ok := w.quietAtPly(p, quiescenceDepth, -searchInfinity, searchInfinity, false, 7)
			if !ok || score != mateScore-8 {
				t.Fatal("mate distance", row.ID, score, ok)
			}
			if score, _ := (&searcher{}).quietAtPly(p, 0, -searchInfinity, searchInfinity, false, 7); score != staticScore(p, p.Turn()) {
				t.Fatal("depth cap extended")
			}
		}
		if p.String() != before || p.ZobristHash() != hash {
			t.Fatal("mutated input")
		}
	}
	if positives != 15 {
		t.Fatal("positive count", positives)
	}
}

func TestQuietMateProofAgainstEnumeration(t *testing.T) {
	rng := rand.New(rand.NewPCG(20, 20261117))
	p := chess.StartingPosition()
	for i := 0; i < 2500; i++ {
		cold := evalFEN(t, p.String())
		m, got := cold.QuietMateMove()
		_, want := quietMateOracle(p)
		if got != want {
			t.Fatalf("cold proof disagreement %s", p)
		}
		if got && cold.Update(&m).Status() != chess.Checkmate {
			t.Fatal("false mate")
		}
		_, warm := p.QuietMateMove()
		if warm != want {
			t.Fatal("cache changes proof")
		}
		moves := p.ValidMoves()
		if len(moves) == 0 || i%100 == 99 {
			p = chess.StartingPosition()
		} else {
			m := moves[rng.IntN(len(moves))]
			p = p.Update(&m)
		}
	}
	for _, fen := range []string{
		"7k/8/6Q1/8/8/8/8/K7 w - - 0 1",     // check with king escapes
		"7k/5Q2/6K1/8/8/8/8/8 b - - 0 1",    // stalemate
		"4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 1", // en passant
		"r3k2r/ppp2ppp/2n5/3pp3/3PP3/2N5/PPP2PPP/R3K2R w KQkq - 0 1",
		"k3r3/8/8/8/8/8/4Q3/4K3 w - - 0 1", // pinned queen
	} {
		p := evalFEN(t, fen)
		_, got := p.QuietMateMove()
		_, want := quietMateOracle(p)
		if got != want {
			t.Fatal("special control", fen)
		}
	}
}

func TestQuietMateProofDiscoveredAndCastling(t *testing.T) {
	for _, tt := range []struct {
		fen    string
		castle bool
	}{
		{"kr6/1p6/8/8/B7/8/8/R6K w - - 0 1", false},
		{"8/8/8/1B6/4ppp1/4pkp1/8/4K2R w K - 0 1", true},
		{"4k2r/8/4PKP1/4PPP1/1b6/8/8/8 b k - 0 1", true},
	} {
		p := evalFEN(t, tt.fen)
		m, ok := p.QuietMateMove()
		_, oracle := quietMateOracle(p)
		if !ok || !oracle || p.Update(&m).Status() != chess.Checkmate {
			t.Fatal("missing proven mate", tt.fen, m)
		}
		if tt.castle && !m.HasTag(chess.KingSideCastle) {
			t.Fatal("expected castle-only mate", tt.fen, m)
		}
	}
}

func TestQuietMateProofCancellationAndRepetition(t *testing.T) {
	p := evalFEN(t, "7k/8/5KQ1/8/8/8/8/8 w - - 0 1")
	start := time.Now()
	calls := 0
	w := searcher{deadline: start.Add(time.Second), now: func() time.Time {
		calls++
		if calls == 1 {
			return start
		}
		return start.Add(2 * time.Second)
	}}
	if _, complete := w.quietAtPly(p, quiescenceDepth, -searchInfinity, searchInfinity, false, 0); complete {
		t.Fatal("late proof accepted after cancellation")
	}
	w = searcher{}
	w.pushPosition(p)
	w.pushPosition(p)
	if score, complete := w.quietAtPly(p, quiescenceDepth, -searchInfinity, searchInfinity, false, 0); !complete || score != 0 {
		t.Fatal("proof bypassed repetition", score, complete)
	}
}

func TestQuietMateProofExcludesEnPassant(t *testing.T) {
	for _, fen := range []string{"8/4NN2/8/R2pP2k/8/4NN2/8/K7 w - d6 0 1", "1rrr4/1pkp4/8/2KpP3/8/8/8/8 w - d6 0 1"} {
		p := evalFEN(t, fen)
		var ep chess.Move
		found := false
		for _, m := range p.ValidMoves() {
			if m.HasTag(chess.EnPassant) {
				ep = m
				found = true
			}
		}
		if !found || p.Update(&ep).Status() != chess.Checkmate {
			t.Fatal("fixture must have an EP mate")
		}
		p = evalFEN(t, p.String()) // Cold path must agree with the cached path.
		if m, got := p.QuietMateMove(); got {
			t.Fatal("tactical EP reported as quiet mate", m)
		}
		if _, got := quietMateOracle(p); got {
			t.Fatal("fixture unexpectedly has another quiet mate")
		}
		if score := quiescence(p, quiescenceDepth, -searchInfinity, searchInfinity); score != mateScore-1 {
			t.Fatal("ordinary tactical EP mate lost", score)
		}
	}
}

