package chess

import "math/bits"

// QuietMateMove returns a legal noncapture, nonpromotion mate in one, if present.
// It proves only an actual move by the current player; no null-move threat or
// recursive checking search is used. Position/cache state remains unchanged.
func (pos *Position) QuietMateMove() (Move, bool) {
	if pos.inCheck {
		return Move{}, false
	} // Checked search already visits every legal evasion.
	if pos.validMoves != nil {
		for _, m := range pos.validMoves {
			if m.HasTag(Check) && !m.HasTag(Capture) && !m.HasTag(EnPassant) && m.Promo() == NoPieceType && !pos.Update(&m).HasLegalMove() {
				return m, true
			}
		}
		return Move{}, false
	}
	board := pos.board
	king := board.kingSquare(pos.turn.Other())
	if king == NoSquare {
		return Move{}, false
	}
	occupied := ^board.emptySqs
	own := board.whiteSqs
	if pos.turn == Black {
		own = board.blackSqs
	}
	rookQueens := board.bbForPiece(NewPiece(Rook, pos.turn)) | board.bbForPiece(NewPiece(Queen, pos.turn))
	bishopQueens := board.bbForPiece(NewPiece(Bishop, pos.turn)) | board.bbForPiece(NewPiece(Queen, pos.turn))
	hv, diagonal := hvAttack(occupied, king), diaAttack(occupied, king)
	visible := (hv | diagonal) & own
	discoveries := bitboard(0)
	for blockers := visible; blockers != 0; {
		s := Square(bits.LeadingZeros64(uint64(blockers)))
		bit := bbForSquare(s)
		blockers &^= bit
		vacated := occupied &^ bit
		if ((hvAttack(vacated, king)&rookQueens)|(diaAttack(vacated, king)&bishopQueens))&^bit != 0 {
			discoveries |= bit
		}
	}
	for _, piece := range allPieces {
		if piece.Color() != pos.turn {
			continue
		}
		for from := board.bbForPiece(piece); from != 0; {
			s1 := Square(bits.LeadingZeros64(uint64(from)))
			bit := bbForSquare(s1)
			from &^= bit
			to := bbForPossibleMoves(pos, piece.Type(), s1) & board.emptySqs
			if piece.Type() == Pawn {
				to &^= bbRank1 | bbRank8
			} // Promotions remain tactical search moves.
			if discoveries&bit == 0 {
				mask := bitboard(0)
				switch piece.Type() {
				case Knight:
					mask = bbKnightMoves[king]
				case Pawn:
					mask = pawnAttacksFrom(pos.turn.Other(), king)
				case Rook:
					mask = hv
					if visible&bit != 0 {
						mask = hvAttack(occupied&^bit, king)
					}
				case Bishop:
					mask = diagonal
					if visible&bit != 0 {
						mask = diaAttack(occupied&^bit, king)
					}
				case Queen:
					mask = hv | diagonal
					if visible&bit != 0 {
						mask = hvAttack(occupied&^bit, king) | diaAttack(occupied&^bit, king)
					}
				}
				to &= mask
			}
			for to != 0 {
				s2 := Square(bits.LeadingZeros64(uint64(to)))
				to &^= bbForSquare(s2)
				m := Move{s1: s1, s2: s2}
				m.tags = moveTags(m, pos)
				if !m.HasTag(inCheck) && m.HasTag(Check) && !pos.Update(&m).HasLegalMove() {
					return m, true
				}
			}
		}
	}
	if pos.castleRights.CanCastle(pos.turn, KingSide) || pos.castleRights.CanCastle(pos.turn, QueenSide) {
		for _, m := range castleMoves(pos) {
			if m.HasTag(Check) && !pos.Update(&m).HasLegalMove() {
				return m, true
			}
		}
	}
	return Move{}, false
}

